using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SyphonHourglassAction", menuName = "Data/Battle/Battle Actions/Sothis/SyphonHourglass Action")]
public class SyphonHourglassAction : GainSandsOfTimeBasedAction
{
	[Header("Syphon Hourglass")]
	[SerializeField]
	private AfflictionReliefEffect reliefEffect;

	[SerializeField]
	private AfflictionReliefEffect afflictionEffect;

	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[SerializeField]
	private int oneEffectSandsOfTimeAmount;

	public int OneEffectSandsOfTimeAmount => oneEffectSandsOfTimeAmount;

	public override int GetSandsOfTimeAmount(int amount = 0)
	{
		int num = 0;
		List<GameObject> list = currentActiveUnits.GetCurrentActiveUnits();
		for (int i = 0; i < list.Count; i++)
		{
			UnitEffects component = list[i].GetComponent<UnitEffects>();
			int num2 = 0;
			if (component.IsEffectActive(reliefEffect, activateFeedback: false))
			{
				num2 += oneEffectSandsOfTimeAmount;
			}
			if (component.IsEffectActive(afflictionEffect, activateFeedback: false))
			{
				num2 += oneEffectSandsOfTimeAmount;
			}
			if (num2 == oneEffectSandsOfTimeAmount * 2)
			{
				num2 = amount;
			}
			num += num2;
		}
		return num;
	}
}
